import{c as e,Q as r,j as n,m as a}from"./chunks/framework.rWdQudnF.js";const h=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-校验码","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-校验码"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/存储与IO系统/校验码.md","filePath":"综合知识/系统基础/计算机组成/存储与IO系统/校验码.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/存储与IO系统/校验码.md"};function s(d,t,l,g,i,c){return r(),n("div",null,[...t[0]||(t[0]=[a('<h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="校验码-★" tabindex="-1">校验码 ★ <a class="header-anchor" href="#校验码-★" aria-label="Permalink to &quot;校验码 ★&quot;">​</a></h3><blockquote><p><strong>码距</strong>：两个编码之间至少需要改变的位数。码距越大，检错纠错能力越强。</p></blockquote><table tabindex="0"><thead><tr><th>校验码</th><th style="text-align:center;">能力</th><th>关键特性</th></tr></thead><tbody><tr><td><strong>奇偶校验</strong></td><td style="text-align:center;">检错（仅奇数位）</td><td>增加 1 位校验位使 1 的个数为奇/偶，码距=2，<strong>不能纠错</strong></td></tr><tr><td><strong>海明码</strong></td><td style="text-align:center;">检错 + <strong>纠错</strong>（1位）</td><td>校验位在 2 的幂次方位置（1,2,4,8...），公式 <strong>2^k ≥ n+k+1</strong></td></tr><tr><td><strong>CRC</strong></td><td style="text-align:center;">检错</td><td>模 2 除法（异或），只能检错<strong>不能纠错</strong>，约定生成多项式 G(x)</td></tr></tbody></table><p><strong>海明码解题流程</strong>：确定校验位数量 k（2^k ≥ n+k+1）→ 校验位放 2 的幂次方位置 → 按位负责关系计算各校验位（偶校验）→ 写出编码。</p><p><strong>CRC 解题流程</strong>：原始信息后补 r 个 0（r = G(x) 最高次）→ G(x) 转二进制除数 → 模 2 除法得余数 → 拼接发送。</p>',6)])])}const p=e(o,[["render",s]]);export{h as __pageData,p as default};
